def det(a, b, c):
	return +a[0] * b[1] * c[2] + a[2] * b[0] * c[1] + a[1] * b[2] * c[0] - a[2] * b[1] * c[0] - a[1] * b[0] * c[2] - a[0] * b[2] * c[1]

def sub(v0, v1):
	return (v0[0] - v1[0], v0[1] - v1[1], v0[2] - v1[2])
