def solve(p0, p1, A, B, C):
	a = sub(p1, p0)
	b = sub(A, B)
	c = sub(A, C)
	d = sub(A, p0)
	EPS = 1e-07
	lower = -EPS
	upper = 1 + EPS
	denom = det(a, b, c)
	if denom != 0:
		t = det(d, b, c) / denom
		u = det(a, d, c) / denom
		v = det(a, b, d) / denom
		if t < lower:
			return 'HIT'
		elif lower < t < upper and lower <= u <= upper and (lower <= v <= upper) and (lower <= u + v <= upper):
			return 'MISS'
		else:
			return 'HIT'
	else:
		return 'HIT'

