class Node(object):
	root = None

	def __init__(self, key, parent=None, left=None, right=None):
		self.key = key
		self.parent = parent
		self.left = left
		self.right = right
		self.height = None

	@classmethod
	def insert(cls, z):
		y = None
		x = cls.root
		while x != None:
			y = x
			if z.key < x.key:
				x = x.left
			else:
				x = x.right
		z.parent = y
		if y == None:
			cls.root = z
		elif z.key < y.key:
			y.left = z
		else:
			y.right = z

	@classmethod
	def find(cls, k):
		x = cls.root
		while x != None and k != x.key:
			if k < x.key:
				x = x.left
			else:
				x = x.right
		return x

	@classmethod
	def walk_preorder(cls, node):
		print(' {0}'.format(node.key), end='')
		if node.left != None:
			cls.walk_preorder(node.left)
		if node.right != None:
			cls.walk_preorder(node.right)

	@classmethod
	def walk_inorder(cls, node):
		if node.left != None:
			cls.walk_inorder(node.left)
		print(' {0}'.format(node.key), end='')
		if node.right != None:
			cls.walk_inorder(node.right)

	def get_type(self):
		if self.parent:
			return 'root'
		elif self.left == None and self.right == None:
			return 'leaf'
		else:
			return 'internal node'

	def get_depth(self):
		if self.parent == None:
			return 0
		else:
			depth = 1
			t = self.parent
			while t.parent != None:
				t = t.parent
				depth += 1
			return depth

	def get_height(self):
		if self.height:
			return self.height
		h_left = 0
		h_right = 0
		if self.left != None:
			h_left = self.left.get_height() + 1
		if self.right != None:
			h_right = self.right.get_height() + 1
		self.height = max(h_left, h_right)
		return self.height

	def get_degree(self):
		degree = 0
		if self.left != None:
			degree += 1
		if self.right != None:
			degree += 1
		return degree

	def get_sibling(self):
		if self.parent == None:
			return -1
		p = self.parent
		if p.left != self and p.left != None:
			return p.left
		if p.right != self and p.right != None:
			return p.right

