class Solution:
	hash = {}

	def numTrees(self, n):
		if n == 0:
			return 1
		if n == 1 or n == 2:
			return n
		try:
			return self.hash[n]
		except KeyError:
			pass
		resSum = 0
		for i in range(n):
			tempSum = self.numTrees(i) * self.numTrees(n - (i + 1))
			resSum += tempSum
		self.hash[n] = resSum
		return resSum

class Solution:

	def diagonalSum(self, mat: List[List[int]]) -> int:
		rows = len(mat)
		columns = len(mat[0])
		sum_ = 0
		for (r, c1, c2) in zip(list(range(rows)), list(range(columns)), list(range(columns - 1, -1, -1))):
			sum_ += mat[r][c1]
			if c1 != c2:
				sum_ += mat[r][c2]
		return sum_

class Solution:

	def findKthBit(self, n: int, k: int) -> str:
		i = n - 1
		invert = False
		while i > 0:
			half_len = (2 ** (i + 1) - 1) // 2
			if k == half_len + 1:
				return '1' if not invert else '0'
			if k > half_len:
				k = half_len - (k - half_len - 1) + 1
				invert = not invert
			i -= 1
		return '1' if invert else '0'

