			(m, l, k) = C[i]
			if t + m > T:
				break
			if t % (l + k) <= l:
				used[i] = 1
				S[t + m] += 1
				cap -= 1
				if i == f:
					while f < N and used[f]:
						f += 1
				if cap == 0:
					break
	cap += S[T]
	return sum(used) == N and cap == x

