class Solution:

	def maxProduct(self, nums: List[int]) -> int:
		if nums[0] > nums[1]:
			largest = nums[0]
			second_largest = nums[1]
		else:
			largest = nums[1]
			second_largest = nums[0]
		for i in range(2, len(nums)):
			if nums[i] > largest:
				second_largest = largest
				largest = nums[i]
			elif nums[i] > second_largest:
				second_largest = nums[i]
		return (largest - 1) * (second_largest - 1)

class TrieNode:

	def __init__(self):
		self.child = {}
		self.count = 0

class Trie:

	def __init__(self):
		self.root = TrieNode()

	def add(self, s):
		node = self.root
		node.count += 1
		for c in s:
			c = ord(c) - 97
			if c not in node.child:
				node.child[c] = TrieNode()
			node = node.child[c]
			node.count += 1
		node.child[26] = TrieNode()
		node.child[26].count += 1

	def query(self, s):
		res = [[0] * 27 for _ in range(26)]
		node = self.root
		for c in s:
			c = ord(c) - 97
			res_c = res[c]
			for (i, child) in node.child.items():
				res_c[i] += child.count
			node = node.child[c]
		return res
