def modpower(a, n, mod):
	r = a ** (n % 2)
	if n > 1:
		r *= modpower(a, n / 2, mod) ** 2
	return r % mod

def modmatrixproduct(a, b, mod):
	(n, m1) = (len(a), len(a[0]))
	(m2, k) = (len(b), len(b[0]))
	assert m1 == m2
	m = m1
	r = [[0] * k for i in range(n)]
	for i in range(n):
		for j in range(k):
			for l in range(m):
				r[i][j] += a[i][l] * b[l][j]
			r[i][j] %= mod
	return r

def modmatrixpower(a, n, mod):
	magic = 2
	for m in [2, 3, 5, 7]:
		if n % m == 0:
			magic = m
			break
	r = None
	if n < magic:
		r = a
		n -= 1
	else:
		s = modmatrixpower(a, n // magic, mod)
		r = s
		for i in range(magic - 1):
			r = modmatrixproduct(r, s, mod)
	for i in range(n % magic):
		r = modmatrixproduct(r, a, mod)
	return r

def gcd(a, b):
	if a > b:
		(a, b) = (b, a)
	while a > 0:
		(a, b) = (b % a, a)
	return b
