def mergesort(l):
	l = list(l)
	if len(l) <= 1:
		return (l, 0)
	(left, linv) = mergesort(l[:len(l) // 2])
	(right, rinv) = mergesort(l[len(l) // 2:])
	lefti = 0
	righti = 0
	i = 0
	numinversions = 0
	while True:
		if i >= len(l):
			break
		if lefti >= len(left):
			l[i] = right[righti]
			righti += 1
		elif righti >= len(right):
			l[i] = left[lefti]
			lefti += 1
			numinversions += len(right)
		elif left[lefti] > right[righti]:
			l[i] = right[righti]
			righti += 1
		else:
			l[i] = left[lefti]
			lefti += 1
			numinversions += righti
		i += 1
	return (l, numinversions + linv + rinv)
