def calSNum(n, r):
	if n == r or r == 1:
		fball[r][n] = 1
		return
	if n > 0 and r > 0 and (n > r):
		fball[r][n] = (fball[r - 1][n - 1] % MOD + r * fball[r][n - 1] % MOD) % MOD
		return
	fball[r][n] = 0

def calASNum(n, r):
	if n == 0 and r == 0:
		cric[r][n] = 0
		return
	if n >= 2 and r == 1:
		cric[r][n] = 1
		return
	if r > 0 and n > 0 and (n >= 2 * r):
		cric[r][n] = (r * cric[r][n - 1] % MOD + (n - 1) * cric[r - 1][n - 2] % MOD) % MOD
		return
	cric[r][n] = 0

