def postorder(g, n):
	visited = set()
	for i in range(n):
		if i in visited:
			continue
		parent_stack = []
		dfs_stack = [(i, None)]
		while dfs_stack:
			(u, prev) = dfs_stack.pop()
			visited |= {u}
			dfs_stack.extend(((t, u) for (d, t) in g[u] if t != prev))
			while parent_stack and parent_stack[-1] != prev:
				yield parent_stack.pop()
			parent_stack.append(u)
		while parent_stack:
			yield parent_stack.pop()

def preorder(g, n):
	visited = set()
	for i in range(n):
		if i in visited:
			continue
		dfs_stack = [(i, None)]
		while dfs_stack:
			(u, prev) = dfs_stack.pop()
			visited |= {u}
			yield u
			dfs_stack.extend(((t, u) for (d, t) in g[u] if t != prev))
